import { describe, expect, it } from "vitest";
import { genomeTrack, geometricSummary, titerPlot } from "../src/science/index.js";
import { tCritical95 } from "../src/science/stats.js";
import { keyedMarks, parse } from "./helpers.js";

describe("geometricSummary", () => {
  it("computes a geometric mean and a t-based 95% interval on the log scale", () => {
    const s = geometricSummary([10, 40, 160]);
    expect(s.mean).toBeCloseTo(40, 10);
    // log values ln10, ln40, ln160: sd = ln4, half-width = 4.303 * ln4 / sqrt(3).
    const half = (4.303 * Math.log(4)) / Math.sqrt(3);
    expect(s.lower).toBeCloseTo(40 / Math.exp(half), 6);
    expect(s.upper).toBeCloseTo(40 * Math.exp(half), 6);
  });

  it("gives no interval for one value and refuses non-positive values", () => {
    const one = geometricSummary([80]);
    expect(one.n).toBe(1);
    expect(one.mean).toBeCloseTo(80, 10);
    expect(one.lower).toBeUndefined();
    expect(() => geometricSummary([0, 1])).toThrow(/positive/);
    expect(() => geometricSummary([])).toThrow(/no values/);
  });

  it("uses published t critical values", () => {
    expect(tCritical95(1)).toBe(12.706);
    expect(tCritical95(10)).toBe(2.228);
    expect(tCritical95(30)).toBe(2.042);
    expect(tCritical95(120)).toBeCloseTo(1.98, 2);
  });
});

describe("titerPlot", () => {
  const sera = [
    { day: "D0", titer: 5 },
    { day: "D0", titer: 10 },
    { day: "D0", titer: 10 },
    { day: "D28", titer: 160 },
    { day: "D28", titer: 320 },
  ];

  it("draws below-limit samples hollow at half the limit", () => {
    const fig = parse(titerPlot({ data: sera, group: "day", titer: "titer", alt: "a" }));
    const marks = keyedMarks(fig);
    expect(marks).toHaveLength(5);
    expect(marks[0]?.getAttribute("fill")).toBe("var(--enarratio-background)");
    expect(marks[1]?.getAttribute("fill")).toBe("var(--enarratio-series-1)");
    expect(marks[0]?.querySelector("title")?.textContent).toBe(
      "day D0: below the limit of detection (<1:10)",
    );
  });

  it("spreads identical titers side by side", () => {
    const fig = parse(titerPlot({ data: sera, group: "day", titer: "titer", alt: "a" }));
    const [, b, c] = keyedMarks(fig);
    expect(b?.getAttribute("cy")).toBe(c?.getAttribute("cy"));
    expect(b?.getAttribute("cx")).not.toBe(c?.getAttribute("cx"));
  });

  it("labels the axis in dilution steps", () => {
    const fig = parse(titerPlot({ data: sera, group: "day", titer: "titer", alt: "a" }));
    const ticks = [...fig.querySelectorAll('[data-enarratio-mark="y-axis tick label"] text')].map(
      (t) => t.textContent,
    );
    expect(ticks).toEqual(["1:5", "1:10", "1:20", "1:40", "1:80", "1:160", "1:320", "1:640"]);
  });

  it("summarizes each group in the table", () => {
    const fig = parse(titerPlot({ data: sera, group: "day", titer: "titer", alt: "a" }));
    const rows = [...fig.querySelectorAll("tbody tr")].map((tr) =>
      [...tr.children].map((c) => c.textContent),
    );
    expect(rows[0]).toEqual(["D0", "3", "7.9", "2.9 to 21.5", "1", "<10, 10, 10"]);
    expect(rows[1]?.[2]).toBe("226");
  });

  it("refuses non-positive titers and a bad dilution series", () => {
    expect(() => titerPlot({ data: [{ g: "a", t: 0 }], group: "g", titer: "t", alt: "a" })).toThrow(
      /positive/,
    );
    expect(() =>
      titerPlot({
        data: sera,
        group: "day",
        titer: "titer",
        dilution: { start: 10, factor: 1 },
        alt: "a",
      }),
    ).toThrow(/factor above 1/);
  });
});

describe("genomeTrack", () => {
  const features = [
    { name: "A", start: 1, end: 400, strand: 1 as const, type: "Gene" },
    { name: "B", start: 300, end: 700, strand: -1 as const, type: "Gene" },
    { name: "C", start: 800, end: 1000, type: "Repeat" },
  ];

  it("draws features as polygons pointing along their strand", () => {
    const fig = parse(genomeTrack({ length: 1000, features, alt: "a" }));
    const marks = keyedMarks(fig);
    expect(marks.map((m) => m.tagName.toLowerCase())).toEqual(["polygon", "polygon", "polygon"]);
    const points = (m: Element | undefined): number =>
      (m?.getAttribute("points") ?? "").split(" ").length;
    expect(points(marks[0])).toBe(5);
    expect(points(marks[1])).toBe(5);
    expect(points(marks[2])).toBe(4);
    expect(marks[0]?.querySelector("title")?.textContent).toBe(
      "A (Gene): 1 to 400, 400 nt, forward strand",
    );
  });

  it("stacks overlapping features into lanes", () => {
    const fig = parse(genomeTrack({ length: 1000, features, alt: "a" }));
    const [a, b, c] = keyedMarks(fig);
    const top = (m: Element | undefined): string =>
      (m?.getAttribute("points") ?? "").split(" ")[0]?.split(",")[1] ?? "";
    expect(top(a)).not.toBe(top(b));
    expect(top(a)).toBe(top(c));
  });

  it("colors and legends by type, and tabulates coordinates", () => {
    const fig = parse(genomeTrack({ length: 1000, features, alt: "a" }));
    expect([...fig.querySelectorAll(".enarratio-legend li")].map((li) => li.textContent)).toEqual([
      "Gene",
      "Repeat",
    ]);
    const rows = [...fig.querySelectorAll("tbody tr")].map((tr) =>
      [...tr.children].map((c) => c.textContent),
    );
    expect(rows[1]).toEqual(["B", "Gene", "300", "700", "401", "-"]);
  });

  it("refuses features outside the sequence", () => {
    expect(() =>
      genomeTrack({ length: 100, features: [{ name: "X", start: 50, end: 150 }], alt: "a" }),
    ).toThrow(/from 1 to 100/);
    expect(() =>
      genomeTrack({ length: 100, features: [{ name: "X", start: 60, end: 50 }], alt: "a" }),
    ).toThrow(/start before end/);
  });
});

test/render.test.ts.source:
/**
 * Rendering tests: the server output of every gallery example, compared with a stored copy, so any
 * change to the markup a site receives is seen in review. Update with `npx vitest run -u` and read
 * the diff before committing it.
 */
import { readdirSync } from "node:fs";
import { basename, join, resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { describe, expect, it } from "vitest";
import { parse } from "./helpers.js";

const examplesDir = resolve(import.meta.dirname, "..", "examples");
const examples = readdirSync(examplesDir).filter((f) => f.endsWith(".ts"));

describe("server rendering", () => {
  it.each(examples)("%s renders the stored markup", async (file) => {
    const module = (await import(pathToFileURL(join(examplesDir, file)).href)) as {
      default: string;
    };
    await expect(module.default).toMatchFileSnapshot(
      join("__snapshots__", "render", `${basename(file, ".ts")}.html`),
    );
  });

  it.each(examples)("%s is well-formed and every svg is named", async (file) => {
    const module = (await import(pathToFileURL(join(examplesDir, file)).href)) as {
      default: string;
    };
    const root = parse(`<div>${module.default}</div>`);
    const svgs = [...root.querySelectorAll("svg")];
    expect(svgs.length).toBeGreaterThan(0);
    for (const svg of svgs) {
      // One image, or a named group when its marks are links.
      expect(["img", "group"]).toContain(svg.getAttribute("role"));
      expect((svg.getAttribute("aria-label") ?? "").length).toBeGreaterThan(0);
    }
    for (const fig of root.querySelectorAll("figure")) {
      expect(fig.hasAttribute("aria-label")).toBe(false);
      expect(fig.querySelector("table")).not.toBeNull();
    }
    // No inline event handlers or scripts can reach the markup.
    expect(module.default).not.toMatch(/<script|\son[a-z]+=/i);
  });
});

test/sparkline.test.ts.source:
import { describe, expect, it } from "vitest";
import { sparkline } from "../src/index.js";
import { parse } from "./helpers.js";

describe("sparkline", () => {
  it("describes the data when no alt is given", () => {
    const svg = parse(sparkline({ values: [2, 5, 3, 8], label: "Entries per year" }));
    expect(svg.getAttribute("role")).toBe("img");
    expect(svg.getAttribute("aria-label")).toBe(
      "Entries per year: 4 values, from 2 to 8; lowest 2, highest 8.",
    );
  });

  it("prefers a given alt", () => {
    const svg = parse(sparkline({ values: [1, 2], alt: "Rising" }));
    expect(svg.getAttribute("aria-label")).toBe("Rising");
  });

  it("breaks the line at nulls instead of drawing zero", () => {
    const svg = parse(sparkline({ values: [1, 2, null, 3, 4], endDot: false }));
    const d = svg.querySelector('path[fill="none"]')?.getAttribute("d") ?? "";
    expect(d.match(/M/g)).toHaveLength(2);
    expect(svg.querySelector("circle")).toBeNull();
  });

  it("draws a flat line mid-height for constant data and a dot at the end", () => {
    const svg = parse(sparkline({ values: [4, 4, 4], height: 20 }));
    expect(svg.querySelector("circle")?.getAttribute("cy")).toBe("10");
  });

  it("shades the area when asked and applies a color override", () => {
    const svg = parse(sparkline({ values: [1, 3], area: true, color: "#123456" }));
    expect(svg.querySelectorAll("path")).toHaveLength(2);
    expect(svg.getAttribute("style")).toBe("--enarratio-series-1: #123456");
  });

  it("refuses empty or non-finite data", () => {
    expect(() => sparkline({ values: [] })).toThrow(/at least one value/);
    expect(() => sparkline({ values: [null] })).toThrow(/at least one value/);
    expect(() => sparkline({ values: [1, Number.POSITIVE_INFINITY] })).toThrow(/value 2/);
  });
});

test/review.test.ts.source:
/**
 * Regression tests for the findings of the two reviews of PR #1 (Fable 5.1: A1 to A17; Claude
 * Opus 5.5: F1 to F23). Each test names the finding it guards. Browser-only findings are in
 * test/browser/review.test.ts.
 */
import { afterEach, describe, expect, it } from "vitest";
import { exampleTheme } from "../examples/themes/example.js";
import {
  checkTheme,
  colorDifference,
  contrastRatio,
  defineTheme,
  progressRing,
  sparkline,
  stylesheet,
  type Theme,
  uptimeStrip,
} from "../src/index.js";
import { areaChart, barChart, heatmap, lineChart, scatterPlot } from "../src/plot/index.js";
import { titerPlot } from "../src/science/index.js";
import { labelColor } from "../src/theme/color.js";
import { defaultTheme } from "../src/themes/index.js";
import { keyedMarks, parse } from "./helpers.js";

const tickLabels = (fig: Element, axis: "x" | "y"): string[] =>
  [...fig.querySelectorAll(`[data-enarratio-mark="${axis}-axis tick label"] text`)].map(
    (t) => t.textContent ?? "",
  );

describe("A1: the default palette and direct labels", () => {
  it("keeps series 1 to 6 at least 10 CIEDE2000 apart for every simulated vision, in both schemes", () => {
    const visions = [undefined, "protanopia", "deuteranopia", "tritanopia"] as const;
    for (const scheme of [defaultTheme.light, defaultTheme.dark]) {
      const six = scheme.series.slice(0, 6);
      for (let i = 0; i < six.length; i += 1) {
        for (let j = i + 1; j < six.length; j += 1) {
          for (const vision of visions) {
            expect(
              colorDifference(six[i] as string, six[j] as string, vision),
            ).toBeGreaterThanOrEqual(10);
          }
        }
      }
    }
    const coreWarnings = checkTheme(defaultTheme).issues.filter((i) => {
      const pair = /series (\d) #\w+ and (\d) /.exec(i.message);
      return i.check === "series-difference" && Number(pair?.[1]) <= 6 && Number(pair?.[2]) <= 6;
    });
    expect(coreWarnings).toEqual([]);
  });

  it("prints series names inside stacked bars that fit, and refuses them on grouped bars", () => {
    const data = Array.from({ length: 12 }, (_, i) => ({
      year: 2020 + (i % 2),
      type: i < 8 ? "Papers" : "Talks",
    }));
    const fig = parse(barChart({ data, x: "year", series: "type", directLabels: true, alt: "a" }));
    const labels = [...fig.querySelectorAll('[data-enarratio-mark="bar label"] text')];
    expect(labels.map((t) => t.textContent)).toContain("Papers");
    expect(labels[0]?.getAttribute("fill")).toMatch(/^var\(--enarratio-series-text-\d\)$/);
    expect(
      fig.querySelector('[data-enarratio-mark="bar label"]')?.getAttribute("aria-hidden"),
    ).toBe("true");
    expect(() =>
      barChart({
        data,
        x: "year",
        series: "type",
        layout: "grouped",
        directLabels: true,
        alt: "a",
      }),
    ).toThrow(/directLabels needs the stacked layout/);
  });
});

describe("A2: count axes end at their last tick", () => {
  it.each([11, 13])("draws every tick inside the plot for %i rows", (n) => {
    const fig = parse(
      barChart({ data: Array.from({ length: n }, () => ({ k: "a" })), x: "k", alt: "a" }),
    );
    const ys = [...fig.querySelectorAll('[data-enarratio-mark="y-axis tick label"] text')].map(
      (t) => Number(/translate\([\d.]+,(-?[\d.]+)\)/.exec(t.getAttribute("transform") ?? "")?.[1]),
    );
    for (const y of ys) expect(y).toBeGreaterThanOrEqual(0);
  });
});

describe("A3: local-midnight Dates are calendar dates", () => {
  const original = process.env["TZ"];
  afterEach(() => {
    if (original === undefined) delete process.env["TZ"];
    else process.env["TZ"] = original;
  });

  it("keeps new Date(2025, 0, 6) as 6 January east of UTC", () => {
    process.env["TZ"] = "Asia/Tokyo";
    const data = [
      { d: new Date(2025, 0, 6), v: 1 },
      { d: new Date(2025, 0, 7), v: 2 },
    ];
    const fig = parse(lineChart({ data, x: "d", y: "v", alt: "a" }));
    expect([...fig.querySelectorAll("tbody th")].map((th) => th.textContent)).toEqual([
      "2025-01-06",
      "2025-01-07",
    ]);
  });
});

describe("A7 and F15: empty and impossible input throws", () => {
  it("refuses empty bar data, all-empty series and non-positive sizes", () => {
    expect(() => barChart({ data: [] as { k: string }[], x: "k", alt: "a" })).toThrow(
      /data is empty/,
    );
    expect(() => lineChart({ data: [{ t: 1, v: null }], x: "t", y: "v", alt: "a" })).toThrow(
      /every value is empty/,
    );
    for (const size of [0, -100, Number.NaN, Number.POSITIVE_INFINITY]) {
      expect(() => barChart({ data: [{ k: "a" }], x: "k", width: size, alt: "a" })).toThrow(
        /width/,
      );
      expect(() =>
        scatterPlot({ data: [{ a: 1, b: 2 }], x: "a", y: "b", height: size, alt: "a" }),
      ).toThrow(/height/);
      expect(() => sparkline({ values: [1, 2], width: size })).toThrow(/width/);
      expect(() => uptimeStrip({ slots: ["up"], label: "x", height: size })).toThrow(/height/);
    }
  });

  it("refuses statuses that are only Object.prototype names", () => {
    for (const status of ["constructor", "toString", "__proto__"]) {
      expect(() => uptimeStrip({ slots: ["up", status as never], label: "x" })).toThrow(
        /unknown status/,
      );
    }
  });

  it("draws a sparkline of 200,000 values without overflowing the stack", () => {
    const values = Array.from({ length: 200_000 }, (_, i) => Math.sin(i / 1000));
    expect(parse(sparkline({ values })).getAttribute("aria-label")).toMatch(/200,000 values/);
  });

  it("refuses a dilution factor too fine to be a dilution series", () => {
    expect(() =>
      titerPlot({
        data: [{ g: "a", t: 1000 }],
        group: "g",
        titer: "t",
        dilution: { start: 10, factor: 1.001 },
        alt: "a",
      }),
    ).toThrow(/over 40 steps/);
  });
});

describe("A8: a number and its text are one category", () => {
  it("draws 2022 and '2022' as one bar and one table row", () => {
    const fig = parse(
      barChart({
        data: [{ y: 2022 }, { y: "2022" }] as { y: number | string }[],
        x: "y",
        alt: "a",
      }),
    );
    expect(keyedMarks(fig)).toHaveLength(1);
    expect(fig.querySelectorAll("tbody tr")).toHaveLength(1);
    expect(fig.querySelector("tbody td")?.textContent).toBe("2");
  });
});

describe("A9 and F14: keys cannot collide", () => {
  it("keeps x 'a|b' in series 'c' apart from x 'a' in series 'b|c'", () => {
    const fig = parse(
      barChart({
        data: [
          { x: "a|b", s: "c" },
          { x: "a", s: "b|c" },
        ],
        x: "x",
        series: "s",
        alt: "a",
      }),
    );
    const keys = keyedMarks(fig).map((m) => m.getAttribute("data-enarratio-key"));
    expect(new Set(keys).size).toBe(2);
  });
});

describe("A10 and F10: theme text cannot break out of CSS", () => {
  const hostile = [
    "x */ body{display:none} /*",
    "x </style><script>alert(1)</script>",
    "x; } body { color: red",
  ];
  it.each(hostile)("refuses %s as a theme name, font, or scheme selector", (payload) => {
    const named = { ...defaultTheme, name: payload } as Theme;
    expect(() => defineTheme(named)).toThrow(/not allowed in CSS/);
    expect(() => stylesheet(named)).toThrow(/not allowed in CSS/);
    const font = { ...defaultTheme, fonts: { body: payload } } as Theme;
    expect(() => stylesheet(font)).toThrow(/not allowed in CSS/);
    expect(() => stylesheet(defaultTheme, { colorScheme: { dark: payload } })).toThrow(
      /not allowed in CSS/,
    );
  });

  it("still accepts ordinary names, font stacks and selectors", () => {
    expect(() =>
      stylesheet(
        {
          ...defaultTheme,
          name: "Lab (2026)",
          fonts: { body: '"Source Serif 4", Georgia, serif' },
        },
        { colorScheme: { dark: '[data-theme="dark"]' } },
      ),
    ).not.toThrow();
  });
});

describe("A11: protocol-relative links are refused", () => {
  it.each(["//evil.example/x", "\\\\evil.example/x", "/\\evil.example", " //evil.example"])(
    "refuses %s",
    (href) => {
      expect(() => barChart({ data: [{ k: "a" }], x: "k", href: () => href, alt: "a" })).toThrow(
        /not a relative or http\(s\) link/,
      );
    },
  );

  it("still accepts root-relative and relative links", () => {
    for (const href of ["/cv?year=1", "cv", "?y=1", "#a"]) {
      expect(() =>
        barChart({ data: [{ k: "a" }], x: "k", href: () => href, alt: "a" }),
      ).not.toThrow();
    }
  });
});

describe("A12: axes are hidden from assistive technology", () => {
  it("marks every axis group aria-hidden", () => {
    const fig = parse(barChart({ data: [{ k: "a" }], x: "k", alt: "a" }));
    const axes = [...fig.querySelectorAll('[data-enarratio-mark*="axis"]')];
    expect(axes.length).toBeGreaterThan(0);
    for (const g of axes) expect(g.getAttribute("aria-hidden")).toBe("true");
  });
});

describe("A13: wide drawings scroll instead of shrinking their text", () => {
  it("wraps the SVG in a frame that keeps a minimum width for wide drawings only", () => {
    const wide = parse(barChart({ data: [{ k: "a" }], x: "k", alt: "a" }));
    expect(wide.querySelector(".enarratio-frame")?.getAttribute("class")).toContain(
      "enarratio-frame-wide",
    );
    const narrow = parse(barChart({ data: [{ k: "a" }], x: "k", width: 300, alt: "a" }));
    expect(narrow.querySelector(".enarratio-frame")?.getAttribute("class")).toBe("enarratio-frame");
    expect(stylesheet(defaultTheme)).toContain(".enarratio-frame-wide > svg { min-width: 30rem; }");
  });
});

describe("F2: a log axis refuses values it cannot show", () => {
  it.each([0, -5])("throws on %i", (bad) => {
    expect(() =>
      lineChart({
        data: [
          { t: 1, v: bad },
          { t: 2, v: 10 },
          { t: 3, v: 100 },
        ],
        x: "t",
        y: "v",
        yType: "log",
        alt: "a",
      }),
    ).toThrow(/which a log axis cannot show/);
  });
});

describe("F3: sub-daily time series", () => {
  it("draws six hourly points as six rows, labelled with the time", () => {
    const data = Array.from({ length: 6 }, (_, h) => ({
      t: new Date(Date.UTC(2026, 0, 1, h)),
      v: h,
    }));
    const fig = parse(lineChart({ data, x: "t", y: "v", alt: "a" }));
    expect(keyedMarks(fig)).toHaveLength(6);
    const rows = [...fig.querySelectorAll("tbody th")].map((th) => th.textContent);
    expect(rows[0]).toBe("2026-01-01 00:00 UTC");
    expect(new Set(rows).size).toBe(6);
  });

  it("keeps rows distinct under a coarse formatX", () => {
    const data = Array.from({ length: 3 }, (_, h) => ({
      t: new Date(Date.UTC(2026, 0, 1, h)),
      v: h,
    }));
    const fig = parse(lineChart({ data, x: "t", y: "v", formatX: () => "Thursday", alt: "a" }));
    expect(keyedMarks(fig)).toHaveLength(3);
  });
});

describe("F4: years print without a thousands separator", () => {
  it("labels the axis and table 2020, not 2,020", () => {
    const fig = parse(
      lineChart({
        data: [2020, 2021, 2022].map((year, i) => ({ year, v: i })),
        x: "year",
        y: "v",
        alt: "a",
      }),
    );
    expect(tickLabels(fig, "x")).toEqual(["2020", "2021", "2022"]);
    expect([...fig.querySelectorAll("tbody th")].map((th) => th.textContent)).toEqual([
      "2020",
      "2021",
      "2022",
    ]);
  });
});

describe("F5: area gaps are gaps", () => {
  it("gives a missing value no point and no hover text claiming zero", () => {
    const fig = parse(
      areaChart({
        data: [
          { d: 1, s: "a", v: 1 },
          { d: 2, s: "a", v: null },
          { d: 3, s: "a", v: 2 },
        ],
        x: "d",
        y: "v",
        series: "s",
        alt: "a",
      }),
    );
    const titles = keyedMarks(fig).map((m) => m.querySelector("title")?.textContent ?? "");
    expect(titles).toHaveLength(2);
    expect(titles.some((t) => t.includes("d 2"))).toBe(false);
    expect([...fig.querySelectorAll("tbody tr")][1]?.querySelector("td")?.textContent).toBe("");
  });
});

describe("F8: labels on marks reach 4.5:1", () => {
  it("chooses a label color with at least 4.5:1 on every fill in both the built-in and the example theme", () => {
    for (const theme of [defaultTheme, exampleTheme]) {
      for (const scheme of [theme.light, theme.dark]) {
        for (const fill of [...scheme.series, ...scheme.sequential]) {
          const label = labelColor(fill, scheme.text, scheme.background);
          expect(contrastRatio(label, fill)).toBeGreaterThanOrEqual(4.5);
        }
      }
      expect(checkTheme(theme).issues.filter((i) => i.check === "label-contrast")).toEqual([]);
    }
  });

  it("falls back to black or white for mid-tone fills", () => {
    for (let v = 0; v <= 255; v += 5) {
      const fill = `#${v.toString(16).padStart(2, "0").repeat(3)}`;
      expect(contrastRatio(labelColor(fill, "#777777", "#888888"), fill)).toBeGreaterThanOrEqual(
        4.5,
      );
    }
  });
});

describe("F9: marks carry their reading order from the data", () => {
  it("numbers grouped bars by category, then series", () => {
    const fig = parse(
      barChart({
        data: [
          { c: "A", s: "one", v: 1 },
          { c: "A", s: "two", v: 2 },
          { c: "B", s: "one", v: 3 },
          { c: "B", s: "two", v: 4 },
        ],
        x: "c",
        y: "v",
        series: "s",
        layout: "grouped",
        alt: "a",
      }),
    );
    expect(
      keyedMarks(fig).map((m) => [
        m.getAttribute("data-enarratio-col"),
        m.getAttribute("data-enarratio-row"),
      ]),
    ).toEqual([
      ["0", "0"],
      ["0", "1"],
      ["1", "0"],
      ["1", "1"],
    ]);
  });

  it("orders a heatmap by column and row", () => {
    const fig = parse(
      heatmap({
        data: [
          { x: "b", y: "q", v: 1 },
          { x: "a", y: "p", v: 2 },
        ],
        x: "x",
        y: "y",
        value: "v",
        xDomain: ["a", "b"],
        yDomain: ["p", "q"],
        alt: "a",
      }),
    );
    const places = keyedMarks(fig).map(
      (m) => `${m.getAttribute("data-enarratio-col")}${m.getAttribute("data-enarratio-row")}`,
    );
    expect(places.sort()).toEqual(["00", "11"]);
  });
});

describe("F13: labels may contain the warning glyph", () => {
  it("draws a category and a reference named with a warning sign", () => {
    expect(() => barChart({ data: [{ k: "⚠ Outage" }], x: "k", alt: "a" })).not.toThrow();
    expect(() =>
      lineChart({
        data: [
          { t: 1, v: 1 },
          { t: 2, v: 2 },
        ],
        x: "t",
        y: "v",
        references: [{ y: 1.5, label: "⚠ limit" }],
        alt: "a",
      }),
    ).not.toThrow();
  });

  it("still throws when Plot itself warns", () => {
    expect(() =>
      scatterPlot({ data: [{ a: "1" as unknown as number, b: 2 }], x: "a", y: "b", alt: "a" }),
    ).toThrow();
  });
});

describe("F18: one name for text alternatives", () => {
  it("accepts alt on every primitive, and label as the subject of a generated one", () => {
    expect(parse(progressRing({ value: 0.5, alt: "Half done" })).getAttribute("aria-label")).toBe(
      "Half done",
    );
    expect(parse(uptimeStrip({ slots: ["up"], alt: "All up" })).getAttribute("aria-label")).toBe(
      "All up",
    );
    expect(parse(sparkline({ values: [1, 2], alt: "Rising" })).getAttribute("aria-label")).toBe(
      "Rising",
    );
    expect(parse(progressRing({ value: 0.5, label: "Done" })).getAttribute("aria-label")).toBe(
      "Done: 50%",
    );
    expect(() => uptimeStrip({ slots: ["up"] })).toThrow(/label or alt is required/);
  });
});

test/primitives.test.ts.source:
import { describe, expect, it } from "vitest";
import { progressRing, uptimeStrip } from "../src/index.js";
import { parse } from "./helpers.js";

describe("progressRing", () => {
  it("states label, value and total, and fills the matching arc", () => {
    const svg = parse(
      progressRing({ value: 3, max: 4, label: "Chapters", size: 40, thickness: 4 }),
    );
    expect(svg.getAttribute("aria-label")).toBe("Chapters: 3 of 4 (75%)");
    const arc = svg.querySelectorAll("circle")[1];
    const circumference = 2 * Math.PI * 18;
    expect(arc?.getAttribute("stroke-dasharray")).toBe(
      `${Math.round(circumference * 0.75 * 100) / 100} ${Math.round(circumference * 100) / 100}`,
    );
    expect(svg.querySelector("text")?.textContent).toBe("75%");
  });

  it("uses a percentage for fractions, says when a value passes the total, and draws no arc at zero (A7)", () => {
    expect(parse(progressRing({ value: 0.5, label: "Done" })).getAttribute("aria-label")).toBe(
      "Done: 50%",
    );
    expect(
      parse(progressRing({ value: 2, label: "Done" })).querySelector("text")?.textContent,
    ).toBe("200%");
    expect(
      parse(progressRing({ value: 3, max: 2, label: "Done" })).getAttribute("aria-label"),
    ).toBe("Done: 3 of 2 (150%, more than the total)");
    expect(
      parse(progressRing({ value: 0, label: "Done" })).querySelectorAll("circle"),
    ).toHaveLength(1);
  });

  it("hides the number on small rings unless asked", () => {
    expect(
      parse(progressRing({ value: 0.5, label: "Done", size: 20 })).querySelector("text"),
    ).toBeNull();
  });

  it("refuses bad values", () => {
    expect(() => progressRing({ value: -1, label: "x" })).toThrow(/zero or more/);
    expect(() => progressRing({ value: 1, max: 0, label: "x" })).toThrow(/above zero/);
    expect(() => progressRing({ value: 1, label: " " })).toThrow(/label or alt is required/);
    // F15: sizes must be real numbers.
    expect(() => progressRing({ value: 1, label: "x", size: Number.NaN })).toThrow(/size/);
    expect(() => progressRing({ value: 1, label: "x", size: 10, thickness: 10 })).toThrow(
      /thickness/,
    );
  });
});

describe("uptimeStrip", () => {
  it("summarizes counts and availability, ignoring unmeasured periods", () => {
    const svg = parse(
      uptimeStrip({
        slots: ["up", "up", "degraded", "down", "unknown"],
        label: "API, last 5 hours",
      }),
    );
    expect(svg.getAttribute("aria-label")).toBe(
      "API, last 5 hours: 5 periods, 2 up, 1 degraded, 1 down, 1 no data; 75% available.",
    );
  });

  it("encodes status by height as well as color", () => {
    const svg = parse(uptimeStrip({ slots: ["up", "degraded", "down"], label: "x", height: 30 }));
    expect([...svg.querySelectorAll("rect")].map((r) => r.getAttribute("height"))).toEqual([
      "30",
      "19.8",
      "9.9",
    ]);
  });

  it("uses per-slot labels in hover details", () => {
    const svg = parse(uptimeStrip({ slots: [{ status: "down", label: "Mon 14:00" }], label: "x" }));
    expect(svg.querySelector("rect title")?.textContent).toBe("Mon 14:00: down");
  });

  it("refuses empty strips and unknown states", () => {
    expect(() => uptimeStrip({ slots: [], label: "x" })).toThrow(/at least one/);
    expect(() => uptimeStrip({ slots: ["sideways" as never], label: "x" })).toThrow(
      /unknown status/,
    );
  });
});

test/forecast.test.ts.source:
/**
 * lineChart's forecast options: `band` (lower and upper fields drawn as a shaded area) and
 * `forecastFrom` (the line dashed after an x). The caller computes the forecast; these tests
 * check that what is drawn, what is hovered and what the data table says are the same numbers.
 */
import { describe, expect, it } from "vitest";
import { lineChart } from "../src/plot/index.js";
import { keyedMarks, parse } from "./helpers.js";

const days = [
  { day: "2026-03-01", cases: 10, lo: null, hi: null },
  { day: "2026-03-02", cases: 14, lo: null, hi: null },
  { day: "2026-03-03", cases: 18, lo: null, hi: null },
  { day: "2026-03-04", cases: 22, lo: 17, hi: 27 },
  { day: "2026-03-05", cases: 26, lo: 19, hi: 34 },
  { day: "2026-03-06", cases: 30, lo: 20, hi: 42 },
];

const base = {
  data: days,
  x: "day",
  y: "cases",
  alt: "Cases per day, forecast from 3 March",
} as const;
const band = { lower: "lo", upper: "hi", label: "95% interval" } as const;

const tableRows = (fig: Element): string[][] =>
  [...fig.querySelectorAll("tbody tr")].map((tr) =>
    [...tr.children].map((c) => c.textContent ?? ""),
  );

describe("lineChart band", () => {
  const fig = parse(lineChart({ ...base, band, forecastFrom: "2026-03-03" }));

  it("draws one shaded area behind the line", () => {
    const area = fig.querySelector('[data-enarratio-mark="area"]');
    expect(area).not.toBeNull();
    expect(area?.querySelectorAll("path")).toHaveLength(1);
    const marks = [...fig.querySelectorAll("svg > g")].map((g) =>
      g.getAttribute("data-enarratio-mark"),
    );
    expect(marks.indexOf("area")).toBeLessThan(marks.indexOf("line"));
  });

  it("draws the band at the lower and upper values, on the same scale as the points", () => {
    // y pixels are linear in value; read the mapping off two points, then check the band's edges.
    const dots = keyedMarks(fig).map((m) => ({
      value: Number(/: (\d+)/.exec(m.querySelector("title")?.textContent ?? "")?.[1]),
      cy: Number(m.getAttribute("cy")),
    }));
    const [a, b] = [dots[0], dots[5]] as [(typeof dots)[number], (typeof dots)[number]];
    const slope = (b.cy - a.cy) / (b.value - a.value);
    const yOf = (v: number): number => a.cy + (v - a.value) * slope;
    const d = fig.querySelector('[data-enarratio-mark="area"] path')?.getAttribute("d") ?? "";
    const ys = [...d.matchAll(/(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/g)].map((m) => Number(m[2]));
    for (const row of days.filter((r) => r.lo !== null && r.hi !== null)) {
      for (const v of [row.lo as number, row.hi as number]) {
        expect(
          ys.some((y) => Math.abs(y - yOf(v)) < 0.05),
          `${row.day} ${v}`,
        ).toBe(true);
      }
    }
    // No area where the rows have no band: 3 rows, 2 edges each.
    expect(ys).toHaveLength(6);
  });

  it("carries the bounds in the data table, as columns, with forecast rows marked", () => {
    const head = [...fig.querySelectorAll("thead th")].map((th) => th.textContent);
    expect(head).toEqual([
      "day",
      "cases",
      "95% interval, lower",
      "95% interval, upper",
      "Forecast",
    ]);
    expect(tableRows(fig)).toEqual(
      days.map((r, i) => [
        r.day,
        String(r.cases),
        r.lo === null ? "" : String(r.lo),
        r.hi === null ? "" : String(r.hi),
        i > 2 ? "Yes" : "",
      ]),
    );
  });

  it("says the same in the hover details as in the table", () => {
    const titles = keyedMarks(fig).map((m) => m.querySelector("title")?.textContent);
    expect(titles[3]).toBe("day 2026-03-04: 22 (forecast; 95% interval 17 to 27)");
    expect(titles[2]).toBe("day 2026-03-03: 18");
  });

  it("names bound columns per series", () => {
    const multi = days.flatMap((r) => [
      { ...r, county: "A" },
      { ...r, county: "B", cases: r.cases + 1, lo: r.lo === null ? null : r.lo + 1, hi: r.hi },
    ]);
    const out = parse(
      lineChart({ ...base, data: multi, series: "county", band: { lower: "lo", upper: "hi" } }),
    );
    expect([...out.querySelectorAll("thead th")].map((th) => th.textContent)).toEqual([
      "day",
      "A",
      "B",
      "A lower bound",
      "A upper bound",
      "B lower bound",
      "B upper bound",
    ]);
    expect(out.querySelectorAll('[data-enarratio-mark="area"] path')).toHaveLength(2);
  });

  it("names bound columns without a label", () => {
    const out = parse(lineChart({ ...base, band: { lower: "lo", upper: "hi" } }));
    expect([...out.querySelectorAll("thead th")].map((th) => th.textContent)).toEqual([
      "day",
      "cases",
      "Lower bound",
      "Upper bound",
    ]);
  });

  it("refuses a band that would draw wrongly", () => {
    const oneSided = days.map((r, i) => (i === 4 ? { ...r, hi: null } : r));
    expect(() => lineChart({ ...base, data: oneSided, band })).toThrow(/only one of the band's/);
    const flipped = days.map((r, i) => (i === 4 ? { ...r, lo: 40 } : r));
    expect(() => lineChart({ ...base, data: flipped, band })).toThrow(/lower bound 40 is above/);
    const bad = days.map((r, i) => (i === 4 ? { ...r, lo: Number.NaN } : r));
    expect(() => lineChart({ ...base, data: bad, band })).toThrow(/finite number/);
    const zero = days.map((r, i) => (i === 3 ? { ...r, lo: 0 } : r));
    expect(() => lineChart({ ...base, data: zero, band, yType: "log" })).toThrow(
      /log axis cannot show/,
    );
  });

  it("leaves a chart without options exactly as it was", () => {
    const plain = lineChart({ ...base });
    expect(plain).not.toContain('stroke-dasharray="6,4"');
    expect(plain).not.toContain('data-enarratio-mark="area"');
  });
});

describe("lineChart forecastFrom", () => {
  const fig = parse(lineChart({ ...base, forecastFrom: "2026-03-03" }));
  // Plot puts the dash pattern on the mark's group, with one path per series inside it.
  const lines = [...fig.querySelectorAll('[data-enarratio-mark="line"]')];

  it("draws a solid line up to the boundary and a dashed one from it, joined", () => {
    expect(lines).toHaveLength(2);
    const [solid, dashed] = lines as [Element, Element];
    expect(solid.getAttribute("stroke-dasharray")).toBeNull();
    expect(dashed.getAttribute("stroke-dasharray")).toBe("6,4");
    const points = (el: Element): string[] =>
      (el.querySelector("path")?.getAttribute("d") ?? "").match(
        /-?\d+(?:\.\d+)?,-?\d+(?:\.\d+)?/g,
      ) ?? [];
    expect(points(solid)).toHaveLength(3);
    // The dashed stretch starts at the solid line's last point.
    expect(points(dashed)).toHaveLength(4);
    expect(points(dashed)[0]).toBe(points(solid)[2]);
  });

  it("draws forecast points hollow and observed ones filled", () => {
    const dots = keyedMarks(fig);
    expect(dots[0]?.getAttribute("fill-opacity")).toBe("1");
    expect(dots[3]?.getAttribute("fill-opacity")).toBe("0");
    expect(dots[3]?.getAttribute("stroke")).toMatch(/--enarratio-series-1/);
  });

  it("labels the boundary and marks forecast rows in the table", () => {
    expect(fig.textContent).toContain("Forecast");
    expect(tableRows(fig).map((r) => r[2])).toEqual(["", "", "", "Yes", "Yes", "Yes"]);
    expect(keyedMarks(fig)[4]?.querySelector("title")?.textContent).toBe(
      "day 2026-03-05: 26 (forecast)",
    );
  });

  it("takes a custom label, and a Date or number for the boundary", () => {
    const labelled = lineChart({ ...base, forecastFrom: "2026-03-03", forecastLabel: "Projected" });
    expect(labelled).toContain("Projected");
    const asDate = lineChart({ ...base, forecastFrom: new Date(Date.UTC(2026, 2, 3)) });
    expect(asDate).toBe(lineChart({ ...base, forecastFrom: "2026-03-03" }));
    const linear = parse(
      lineChart({
        data: [1, 2, 3, 4].map((t) => ({ t, v: t * 2 })),
        x: "t",
        y: "v",
        forecastFrom: 2,
        alt: "a",
      }),
    );
    expect(tableRows(linear).map((r) => r.at(-1))).toEqual(["", "", "Yes", "Yes"]);
  });

  it("keeps each series joined when a series has no point at the boundary", () => {
    const rows = [
      { t: 1, s: "A", v: 1 },
      { t: 2, s: "A", v: 2 },
      { t: 4, s: "A", v: 4 },
      { t: 1, s: "B", v: 3 },
      { t: 3, s: "B", v: 3 },
      { t: 4, s: "B", v: 5 },
    ];
    const out = parse(
      lineChart({ data: rows, x: "t", y: "v", series: "s", forecastFrom: 3, alt: "a" }),
    );
    const dashed = [
      ...(out
        .querySelector('[data-enarratio-mark="line"][stroke-dasharray]')
        ?.querySelectorAll("path") ?? []),
    ];
    // Series A has no point at 3, so its dashes start from its point at 2.
    const counts = dashed.map((p) => (p.getAttribute("d") ?? "").match(/,/g)?.length);
    expect(counts.sort()).toEqual([2, 2]);
  });

  it("refuses a boundary with nothing on one side", () => {
    expect(() => lineChart({ ...base, forecastFrom: "2026-03-06" })).toThrow(/forecastFrom/);
    expect(() => lineChart({ ...base, forecastFrom: "2026-02-01" })).toThrow(/forecastFrom/);
    expect(() => lineChart({ ...base, forecastFrom: "soon" })).toThrow(/not a date/);
  });

  it("works with a band and a log axis", () => {
    const fig2 = parse(
      lineChart({ ...base, band, forecastFrom: "2026-03-03", yType: "log", zero: false }),
    );
    expect(fig2.querySelectorAll('[data-enarratio-mark="area"] path')).toHaveLength(1);
  });
});

