/**
 * Documentation stays complete: every public export has a section in docs/api.md, and every
 * chart in the gallery is named in the README.
 */
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";

const root = resolve(import.meta.dirname, "..");
const read = (path: string): string => readFileSync(resolve(root, path), "utf8");

function exportedNames(source: string): string[] {
  const names = new Set<string>();
  for (const block of source.matchAll(/export (?:type )?\{([^}]*)\}/g)) {
    for (const part of (block[1] ?? "").split(",")) {
      const name = part.replace(/\btype\b/, "").trim();
      if (name) names.add(name);
    }
  }
  for (const match of source.matchAll(/^export (?:function|interface|type|const|class) (\w+)/gm)) {
    if (match[1]) names.add(match[1]);
  }
  return [...names];
}

const ENTRIES = [
  "src/index.ts",
  "src/plot/index.ts",
  "src/science/index.ts",
  "src/themes/index.ts",
  "src/enhance/index.ts",
];

describe("documentation", () => {
  const api = read("docs/api.md");
  const publicNames = [...ENTRIES.flatMap((entry) => exportedNames(read(entry)))];

  it("finds the public API", () => {
    expect(publicNames).toContain("barChart");
    expect(publicNames).toContain("enhance");
    expect(publicNames.length).toBeGreaterThan(50);
  });

  it.each(publicNames)("documents %s in docs/api.md", (name) => {
    expect(api).toContain(`### \`${name}\``);
  });

  it("names every chart function in the README", () => {
    const readme = read("README.md");
    for (const name of publicNames.filter(
      (n) =>
        /^[a-z]/.test(n) &&
        /Chart$|Plot$|^heatmap$|Track$|^sparkline$|^progressRing$|^uptimeStrip$/.test(n),
    )) {
      expect(readme).toContain(`\`${name}\``);
    }
  });
});

test/theme.test.ts.source:
import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { exampleTheme } from "../examples/themes/example.js";
import {
  baseStylesheet,
  checkTheme,
  colorDifference,
  contrastRatio,
  defineTheme,
  simulateColorVision,
  stylesheet,
  type Theme,
} from "../src/index.js";
import { deltaE2000 } from "../src/theme/color.js";
import { defaultTheme } from "../src/themes/index.js";

describe("contrastRatio", () => {
  it("is 21 for black on white and 1 for a color on itself", () => {
    expect(contrastRatio("#000000", "#ffffff")).toBeCloseTo(21, 5);
    expect(contrastRatio("#777", "#777777")).toBe(1);
  });

  it("matches a published WCAG value", () => {
    // #767676 on white is the classic lightest gray to pass 4.5:1.
    expect(contrastRatio("#767676", "#fff")).toBeCloseTo(4.54, 2);
  });

  it("rejects colors it cannot measure", () => {
    expect(() => contrastRatio("red", "#fff")).toThrow(/not a hex color/);
  });
});

describe("deltaE2000", () => {
  // Test pairs 1, 7, 17 and 25 of Sharma, Wu and Dalal (2005), Color Res. Appl. 30(1), Table 1.
  it.each([
    [[50, 2.6772, -79.7751], [50, 0, -82.7485], 2.0425],
    [[50, 0, 0], [50, -1, 2], 2.3669],
    [[50, 2.5, 0], [73, 25, -18], 27.1492],
    [[60.2574, -34.0099, 36.2677], [60.4626, -34.1751, 39.4387], 1.2644],
  ] as const)("matches the published difference for %j and %j", (a, b, expected) => {
    expect(deltaE2000(a, b)).toBeCloseTo(expected, 3);
    expect(deltaE2000(b, a)).toBeCloseTo(expected, 3);
  });
});

describe("color vision simulation", () => {
  it("leaves grays unchanged", () => {
    const [r, g, b] = simulateColorVision("#808080", "deuteranopia");
    expect(r).toBeCloseTo(g, 2);
    expect(g).toBeCloseTo(b, 2);
  });

  it("collapses red and green under deuteranopia but not typical vision", () => {
    const typical = colorDifference("#d62728", "#2ca02c");
    const deutan = colorDifference("#d62728", "#2ca02c", "deuteranopia");
    expect(typical).toBeGreaterThan(40);
    expect(deutan).toBeLessThan(typical / 2);
  });

  it("measures zero difference between identical colors", () => {
    expect(colorDifference("#123456", "#123456", "tritanopia")).toBe(0);
  });
});

describe("checkTheme", () => {
  it("passes the built-in theme and the gallery's example theme with no errors", () => {
    expect(checkTheme(defaultTheme).ok).toBe(true);
    expect(checkTheme(exampleTheme).ok).toBe(true);
  });

  it("reports low text contrast as an error, per scheme", () => {
    const pale: Theme = { ...defaultTheme, light: { ...defaultTheme.light, mutedText: "#bbbbbb" } };
    const report = checkTheme(pale);
    expect(report.ok).toBe(false);
    const issue = report.issues.find((i) => i.check === "text-contrast");
    expect(issue).toMatchObject({
      severity: "error",
      scheme: "light",
      colors: ["#bbbbbb", "#ffffff"],
    });
  });

  it("warns once per pair of series colors that could be confused", () => {
    const [first, , ...rest] = defaultTheme.light.series;
    const confusable: Theme = {
      ...defaultTheme,
      light: { ...defaultTheme.light, series: [first, first, ...rest] },
    };
    const warnings = checkTheme(confusable).issues.filter(
      (i) =>
        i.check === "series-difference" &&
        i.message.includes("series 1 ") &&
        i.message.includes(" 2 "),
    );
    expect(warnings).toHaveLength(1);
    expect(warnings[0]?.measured).toBe(0);
  });

  it("errors when the sequential ramp does not grow away from the background", () => {
    const [a, b, c, d, e] = defaultTheme.light.sequential;
    const reversed: Theme = {
      ...defaultTheme,
      light: { ...defaultTheme.light, sequential: [e, d, c, b, a] },
    };
    expect(checkTheme(reversed).issues.some((i) => i.check === "sequential-order")).toBe(true);
  });
});

describe("defineTheme", () => {
  it("returns a valid theme unchanged", () => {
    expect(defineTheme(defaultTheme)).toBe(defaultTheme);
  });

  it("rejects a non-hex color with its path", () => {
    const bad = {
      ...defaultTheme,
      dark: { ...defaultTheme.dark, grid: "gray" },
    } as unknown as Theme;
    expect(() => defineTheme(bad)).toThrow(/dark\.grid: "gray" is not a hex color/);
  });

  it("rejects a palette of the wrong length", () => {
    const short = {
      ...defaultTheme,
      light: { ...defaultTheme.light, series: defaultTheme.light.series.slice(0, 6) },
    } as unknown as Theme;
    expect(() => defineTheme(short)).toThrow(/exactly 8 colors/);
  });
});

describe("stylesheet", () => {
  const css = stylesheet(defaultTheme);

  it("defines every palette slot with a light fallback and a light-dark() pair", () => {
    for (let i = 1; i <= 8; i += 1) {
      expect(css).toContain(`--enarratio-series-${i}: ${defaultTheme.light.series[i - 1]};`);
      expect(css).toContain(
        `--enarratio-series-${i}: light-dark(${defaultTheme.light.series[i - 1]}, ${defaultTheme.dark.series[i - 1]});`,
      );
    }
  });

  it("hides the gridlines the theme does not show", () => {
    expect(css).toContain('[data-enarratio-mark="x-grid"] { display: none; }');
    expect(css).not.toContain('[data-enarratio-mark="y-grid"] { display: none; }');
  });

  it("switches scheme under caller selectors", () => {
    const attr = stylesheet(defaultTheme, { colorScheme: { dark: '[data-theme="dark"]' } });
    expect(attr).toContain(':where([data-theme="dark"]) .enarratio { color-scheme: dark; }');
  });

  it("turns animation off under reduced motion", () => {
    expect(css).toMatch(/@media \(prefers-reduced-motion: reduce\)[^}]*animation: none/);
  });
});

describe("the CSS custom property contract", () => {
  const base = baseStylesheet();
  const api = readFileSync(resolve(import.meta.dirname, "..", "docs", "api.md"), "utf8");
  // Every `var(--enarratio-name, fallback)` the base rules use for a size, weight, radius or timing.
  const tunable = new Map<string, string>();
  for (const m of base.matchAll(/var\((--enarratio-[a-z-]+),\s*((?:[^()]|\([^()]*\))+)\)/g)) {
    tunable.set(m[1] as string, (m[2] as string).replace(/\s+/g, " ").trim());
  }

  it("finds the tunable properties", () => {
    expect(tunable.size).toBeGreaterThan(30);
    expect(tunable.get("--enarratio-font-size-mark")).toBe("12px");
    expect(tunable.get("--enarratio-duration-grow")).toBe("600ms");
  });

  it.each([...tunable])("documents %s with its fallback %s", (name, fallback) => {
    const row = api.split("\n").find((line) => line.startsWith(`| \`${name}\``));
    expect(row, `${name} is missing from the property table in docs/api.md`).toBeDefined();
    expect(row).toContain(`\`${fallback}\``);
  });

  it("is included, unchanged, in every stylesheet", () => {
    expect(stylesheet(defaultTheme)).toContain(base);
  });

  it("defines no theme value itself", () => {
    expect(base).not.toMatch(/--enarratio-(?:series|sequential|status)-\d*[a-z-]*:/);
    expect(base).not.toMatch(/#[0-9a-f]{3,6}\b/i);
  });

  it("ships as dist/base.css when built", () => {
    const built = resolve(import.meta.dirname, "..", "dist", "base.css");
    if (existsSync(built)) expect(readFileSync(built, "utf8").trim()).toBe(base.trim());
  });
});

test/companions.test.ts.source:
/**
 * Companion functions: every primitive offers its numbers as a table and a summary sentence,
 * computed from the same values as the drawing. Each test reads the drawing back and compares it
 * with the table, so the two cannot drift apart.
 */
import { describe, expect, it } from "vitest";
import {
  heatStrip,
  heatStripTable,
  progressRing,
  progressRingTable,
  sparkline,
  sparklineTable,
  timeline,
  timelineTable,
  uptimeStrip,
  uptimeStripTable,
} from "../src/index.js";
import { parse } from "./helpers.js";

const cells = (table: { rows: readonly (readonly string[])[] }, col: number): string[] =>
  table.rows.map((r) => r[col] ?? "");

describe("sparklineTable", () => {
  const options = { values: [3, 8, null, 5, 11], label: "Entries per year", height: 40 };
  const { summary, table, markup } = sparklineTable(options);

  it("states the values the sparkline's text alternative states", () => {
    expect(summary).toBe("Entries per year: 5 values, from 3 to 11; lowest 3, highest 11.");
    expect(parse(sparkline(options)).getAttribute("aria-label")).toBe(summary);
  });

  it("tabulates every position, with no data for a gap", () => {
    expect(table.columns).toEqual(["Position", "Entries per year"]);
    expect(table.rows).toEqual([
      ["1", "3"],
      ["2", "8"],
      ["3", "no data"],
      ["4", "5"],
      ["5", "11"],
    ]);
  });

  it("matches the drawn line: its heights read back as the tabulated values", () => {
    const d =
      parse(sparkline(options)).querySelector("path:not([fill-opacity])")?.getAttribute("d") ?? "";
    const ys = [...d.matchAll(/[ML]([\d.]+),([\d.]+)/g)].map((m) => Number(m[2]));
    // The drawing maps min..max onto height-2.5..2.5 (an inset of 2.5), so invert it.
    const read = ys.map((y) => 3 + ((40 - 2.5 - y) * (11 - 3)) / (40 - 5));
    const present = [3, 8, 5, 11];
    expect(read).toHaveLength(present.length);
    for (const [i, v] of read.entries()) expect(v).toBeCloseTo(present[i] as number, 1);
    expect(cells(table, 1).filter((c) => c !== "no data")).toEqual(present.map(String));
  });

  it("formats with formatValue and gives markup that follows the figure's convention", () => {
    const out = sparklineTable({ values: [1, 2], label: "x", formatValue: (n) => `${n}%` });
    expect(cells(out.table, 1)).toEqual(["1%", "2%"]);
    const root = parse(markup);
    expect(root.localName).toBe("details");
    expect(root.querySelector("caption")?.textContent).toBe("Data for: Entries per year");
    expect(root.querySelectorAll("tbody tr")).toHaveLength(5);
    const hidden = parse(sparklineTable(options, { dataTable: "visually-hidden" }).markup);
    expect(hidden.localName).toBe("div");
    expect(hidden.getAttribute("class")).toContain("enarratio-visually-hidden");
  });

  it("keeps the generated summary when alt is given, and validates like the sparkline", () => {
    expect(sparklineTable({ values: [1], alt: "Mine" }).summary).toBe(
      "1 values, from 1 to 1; lowest 1, highest 1.",
    );
    expect(() => sparklineTable({ values: [] })).toThrow(/at least one value/);
    expect(() => sparklineTable({ values: [1], width: -1 })).toThrow(/width/);
  });
});

describe("uptimeStripTable", () => {
  const slots = [
    "up",
    "up",
    { status: "degraded", label: "Mon 14:00, slow" },
    "down",
    "unknown",
  ] as const;
  const options = { slots, label: "API, last 5 hours" };
  const { summary, table } = uptimeStripTable(options);

  it("states the counts and availability the strip's text alternative states", () => {
    expect(summary).toBe(
      "API, last 5 hours: 5 periods, 2 up, 1 degraded, 1 down, 1 no data; 75% available.",
    );
    expect(parse(uptimeStrip(options)).getAttribute("aria-label")).toBe(summary);
  });

  it("tabulates each period with its status, named as in the hover details", () => {
    expect(table.rows).toEqual([
      ["Period 1", "up"],
      ["Period 2", "up"],
      ["Mon 14:00, slow", "degraded"],
      ["Period 4", "down"],
      ["Period 5", "no data"],
    ]);
    const titles = [...parse(uptimeStrip(options)).querySelectorAll("rect title")].map(
      (t) => t.textContent,
    );
    expect(titles).toEqual(table.rows.map((r) => `${r[0]}: ${r[1]}`));
  });

  it("uses the given alt as the summary when there is no label", () => {
    expect(uptimeStripTable({ slots: ["up"], alt: "Mine" }).summary).toBe("Mine");
    expect(() => uptimeStripTable({ slots: [] })).toThrow(/at least one slot/);
    expect(() => uptimeStripTable({ slots: ["constructor" as never], label: "x" })).toThrow(
      /unknown status/,
    );
  });
});

describe("progressRingTable", () => {
  const options = { value: 7, max: 12, label: "Chapters drafted" };
  const { summary, table } = progressRingTable(options);

  it("states the value, total and percentage the ring's text alternative states", () => {
    expect(summary).toBe("Chapters drafted: 7 of 12 (58%)");
    expect(parse(progressRing(options)).getAttribute("aria-label")).toBe(summary);
  });

  it("tabulates the numbers the ring draws", () => {
    expect(table.columns).toEqual(["Measure", "Value", "Total", "Percent"]);
    expect(table.rows).toEqual([["Chapters drafted", "7", "12", "58%"]]);
    const root = parse(progressRing({ ...options, size: 100, thickness: 10 }));
    const arc = root.querySelectorAll("circle")[1]?.getAttribute("stroke-dasharray") ?? "";
    const [filled, whole] = arc.split(" ").map(Number) as [number, number];
    expect(Math.round((filled / whole) * 100)).toBe(58);
    expect(root.querySelector("text")?.textContent).toBe(table.rows[0]?.[3]);
  });

  it("says when the value passes the total, and handles a ring named only by alt", () => {
    expect(progressRingTable({ value: 1.2, label: "Tests" }).summary).toBe(
      "Tests: 120%, more than the total",
    );
    expect(progressRingTable({ value: 1, alt: "Mine" }).summary).toBe("Mine");
    expect(() => progressRingTable({ value: -1, label: "x" })).toThrow(/zero or more/);
  });
});

describe("heatStripTable", () => {
  const options = {
    values: [3, 5, null, 9, 14],
    label: "Requests per hour",
    cellLabels: ["a", "b", "c", "d", "e"],
  };
  const { summary, table } = heatStripTable(options);

  it("states what the strip's text alternative states", () => {
    expect(summary).toBe(
      "Requests per hour: 5 cells, from 3 to 14; lowest 3, highest 14; 1 with no data.",
    );
    expect(parse(heatStrip(options)).getAttribute("aria-label")).toBe(summary);
  });

  it("tabulates each cell's value and ramp step, as drawn", () => {
    expect(table.columns).toEqual(["Cell", "Value", "Ramp step"]);
    expect(table.rows).toEqual([
      ["a", "3", "1"],
      ["b", "5", "1"],
      ["c", "no data", ""],
      ["d", "9", "3"],
      ["e", "14", "5"],
    ]);
    const drawn = [...parse(heatStrip(options)).querySelectorAll("rect")];
    drawn.forEach((cell, i) => {
      const step = table.rows[i]?.[2];
      expect(cell.getAttribute("fill")).toBe(step ? `var(--enarratio-sequential-${step})` : "none");
      expect(cell.querySelector("title")?.textContent).toBe(
        `${table.rows[i]?.[0]}: ${table.rows[i]?.[1]}`,
      );
    });
  });
});

describe("timelineTable", () => {
  const options = {
    label: "Agent runs",
    start: "2026-06-09T00:00:00Z",
    end: "2026-06-09T08:00:00Z",
    events: [
      { lane: "B", label: "Timeout", status: "error", at: "2026-06-09T03:00:00Z" },
      {
        lane: "A",
        label: "Run",
        status: "ok",
        from: "2026-06-09T01:00:00Z",
        to: "2026-06-09T02:00:00Z",
      },
    ],
  } as const;
  const { summary, table } = timelineTable(options);

  it("states what the timeline's text alternative states", () => {
    expect(summary).toBe(
      "Agent runs: 2 events in 2 lanes, 2026-06-09 00:00 UTC to 2026-06-09 08:00 UTC; 1 ok, 1 error.",
    );
    expect(parse(timeline(options)).querySelector("svg")?.getAttribute("aria-label")).toBe(summary);
  });

  it("tabulates every event in time order, the end blank for a point", () => {
    expect(table.columns).toEqual(["Event", "Lane", "Status", "Start", "End"]);
    expect(table.rows).toEqual([
      ["Run", "A", "ok", "2026-06-09 01:00 UTC", "2026-06-09 02:00 UTC"],
      ["Timeout", "B", "error", "2026-06-09 03:00 UTC", ""],
    ]);
  });

  it("agrees with the drawing's plain list and hover text", () => {
    const root = parse(timeline(options));
    const list = [...root.querySelectorAll("li")].map((li) => li.textContent);
    expect(list).toHaveLength(table.rows.length);
    table.rows.forEach((row, i) => {
      expect(list[i]).toContain(row[0]);
      expect(list[i]).toContain(row[1]);
      expect(list[i]).toContain(row[2]);
      expect(list[i]).toContain(row[3]);
    });
    const titles = [...root.querySelectorAll('[data-enarratio-mark="event"] title')].map(
      (t) => t.textContent,
    );
    expect(titles.sort()).toEqual(
      table.rows
        .map((r) => `${r[1]}: ${r[0]}, ${r[2]}, ${r[4] ? `from ${r[3]} to ${r[4]}` : r[3]}`)
        .sort(),
    );
  });

  it("validates like the timeline", () => {
    expect(() => timelineTable({ ...options, events: [] })).toThrow(/at least one event/);
    expect(() => timelineTable({ events: options.events })).toThrow(/label or alt/);
  });
});
